from datetime import datetime,timezone
import subprocess,json
r={'utc':datetime.now(timezone.utc).isoformat()}
for name,command in [('physical_memory',['/usr/sbin/sysctl','hw.memsize']),('swap',['/usr/sbin/sysctl','vm.swapusage']),('vm_stat',['/usr/bin/vm_stat'])]:
 p=subprocess.run(command,text=True,capture_output=True,timeout=10);r[name]={'command':command,'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
print(json.dumps(r))
